102	  type PromptCardConnection {
103	    edges: [PromptCardEdge!]!
104	    pageInfo: PageInfo!
105	    totalCount: Int!
106	  }
107	
108	  input PromptCardFilterInput {
109	    key: String
110	    scale: String
111	    mood: String
112	    medium: String
113	    style: String
114	    primaryColor: String
