119	    harmonyId: ID!
120	    moodId: ID!
121	    techniqueId: ID!
122	    description: String!
123	  }
124	
125	  type Query {
126	    "Retrieve a prompt by id"
127	    promptCard(id: ID!): PromptCard
128	
129	    "Relay-style paginated prompts"
130	    promptCards(
131	      first: Int = 20
132	      after: String
133	      last: Int
134	      before: String
135	      filter: PromptCardFilterInput
136	    ): PromptCardConnection!
137	
