148	/* -------------------------------------------------------------------------- */
149	/*                           Helper – cursor utils                            */
150	/* -------------------------------------------------------------------------- */
151	
152	const encodeCursor = (str) => Buffer.from(String(str)).toString('base64');
153	const decodeCursor = (cursor) => {
154	  try {
155	    return Buffer.from(cursor, 'base64').toString('utf8');
156	  } catch (e) {
157	    logger.warn({ cursor }, 'Malformed cursor received');
158	    return null;
159	  }
160	};
161	
162	/* -------------------------------------------------------------------------- */
163	/*                              Root Resolvers                                */
164	/* -------------------------------------------------------------------------- */
165	
166	export const resolvers = {
167	  DateTime: DateTimeScalar,
168	
169	  /* ------------------------------- Queries -------------------------------- */
170	  Query: {
171	    async promptCard(_, { id }, { dataSources }) {
172	      return dataSources.promptCardDS.findById(id);
173	    },
174	
175	    async promptCards(_, args, { dataSources }) {
176	      const { first, after, last, before, filter } = args;
177	
178	      if (first && last)
179	        throw new Error('Cannot paginate with both "first" and "last" arguments');
180	
181	      const limit = first ?? last ?? 20;
182	      const cursor = after ?? before;
183	      let offset = cursor ? Number(decodeCursor(cursor)) : 0;
184	
185	      if (before) offset = Math.max(offset - limit, 0);
186	
187	      const { list, totalCount } = await dataSources.promptCardDS.list({
188	        filter,
189	        offset,
190	        limit,
191	      });
192	
193	      const edges = list.map((node) => ({
194	        node,
195	        cursor: encodeCursor(node.id),
196	      }));
197	
198	      return {
199	        edges,
200	        totalCount,
201	        pageInfo: {
202	          hasPreviousPage: offset > 0,
203	          hasNextPage: offset + limit < totalCount,
204	          startCursor: edges[0]?.cursor ?? null,
205	          endCursor: edges.at(-1)?.cursor ?? null,
206	        },
207	      };
208	    },
209	
210	    async randomPromptCard(_, { filter }, { dataSources }) {
211	      const card = await dataSources.promptCardDS.random(filter);
212	      if (!card) throw new Error('No prompt matching the criteria was found');
213	      return card;
214	    },
215	  },
216	
217	  /* ------------------------------ Mutations ------------------------------- */
218	  Mutation: {
219	    async createPromptCard(_, { input }, { dataSources, logger: reqLogger }) {
220	      try {
221	        const card = await dataSources.promptCardDS.create(input);
222	        reqLogger.info({ id: card.id }, 'GraphQL: prompt created');
223	        return card;
224	      } catch (err) {
225	        reqLogger.error({ err }, 'GraphQL: prompt creation failed');
226	        throw err;
227	      }
228	    },
229	  },
230	
231	  /* --------------------------- Nested Resolvers --------------------------- */
232	  PromptCard: {
233	    palette: ({ paletteId }, _, { loaders }) => loaders.palette.load(paletteId),
234	    harmony: ({ harmonyId }, _, { loaders }) => loaders.harmony.load(harmonyId),
235	    mood: ({ moodId }, _, { loaders }) => loaders.mood.load(moodId),
236	    technique: ({ techniqueId }, _, { loaders }) => loaders.technique.load(techniqueId),
237	  },
238	};
