2	/**
3	 * canvaschord-api/src/controllers/prompt.controller.js
4	 *
5	 * Central command module for Prompt–related operations.
6	 * The controller NEVER speaks HTTP/GraphQL directly; instead it receives an
7	 * `express` req/res object or a pure arguments bag from GraphQL resolvers.
8	 * This enables reuse of the same business-logic across transports.
9	 *
10	 * Responsibilities
11	 *  - Guard rails: validation, rate-limiting (delegated to middleware), version branching
12	 *  - Delegation: hand off to service layer for heavy lifting
13	 *  - Observability: structured logging & Prometheus metrics
14	 *
15	 * NOTE: **Do not** introduce DB queries or heavy computation in this file.
16	 */
17	
18	'use strict';
19	
20	/* ────────────────────────────────────────────────────────────────── Imports ─┐ */
21	const { validationResult, matchedData } = require('express-validator');
22	const httpStatus = require('http-status');
23	const createError = require('http-errors');
24	const { v4: uuid } = require('uuid');
25	
26	/* Service & util layers */
27	const promptService = require('../services/prompt.service');
28	const logger = require('../utils/logger');
29	const metrics = require('../utils/metrics');
30	/* ────────────────────────────────────────────────────────────────────────────┘ */
31	
32	/**
33	 * Helper: Picks the correct implementation for the requested version.
34	 * We keep this switch here so that callers don't worry about which
35	 * function to invoke—just pass `req.params.version`.
36	 *
37	 * @param {'v1'|'v2'} version – semantic API version
38	 * @returns {object}          – map of functions (generate, list, create, etc.)
39	 */
40	function selectVersionedImplementation(version) {
41	  switch (version) {
42	    case 'v2':
43	      // Future-proof: will eventually import v2 service with refined schemas
44	      return promptService.v2;
45	    case 'v1':
46	    default:
47	      return promptService.v1;
48	  }
49	}
50	
51	/* ───────────────────────────────────────────────────── REST End-points ───── */
52	
53	/**
54	 * GET /:version/prompts/random
55	 * Returns one randomly-generated prompt. Optional filters (palette, mood, key, etc.)
56	 *
57	 * Express usage:
58	 *   router.get('/:version/prompts/random',
59	 *              validator.randomPrompt,
60	 *              rateLimiter(),
61	 *              promptController.getRandomPrompt);
62	 */
63	async function getRandomPrompt(req, res, next) {
64	  const version = req.params.version || 'v1';
65	  const impl = selectVersionedImplementation(version);
66	
67	  try {
68	    /* Validation guard ********************************************************/
69	    const errors = validationResult(req);
70	    if (!errors.isEmpty()) {
71	      logger.debug('Validation failed for getRandomPrompt', { errors: errors.array() });
72	      return res.status(httpStatus.BAD_REQUEST).json({ errors: errors.array() });
73	    }
74	
75	    const filters = matchedData(req, { locations: ['query'] });
76	    const correlationId = req.headers['x-correlation-id'] || uuid();
77	
78	    /* Business logic **********************************************************/
79	    const endTimer = metrics.randomPromptDuration.startTimer();
80	    const prompt = await impl.generateRandomPrompt(filters);
81	    endTimer();
82	
83	    /* Response ****************************************************************/
84	    res
85	      .status(httpStatus.OK)
86	      .set('x-correlation-id', correlationId)
87	      .json({ data: prompt, meta: { version } });
88	
89	    logger.info('Random prompt delivered', { correlationId, version, filters });
90	  } catch (err) {
91	    logger.error('Random prompt generation failed', { err, version });
92	    next(err);
93	  }
94	}
95	
96	/**
97	 * GET /:version/prompts
98	 * Returns paginated prompt list
99	 */
100	async function listPrompts(req, res, next) {
101	  const version = req.params.version || 'v1';
102	  const impl = selectVersionedImplementation(version);
103	
104	  try {
105	    const errors = validationResult(req);
106	    if (!errors.isEmpty()) {
107	      return res.status(httpStatus.BAD_REQUEST).json({ errors: errors.array() });
108	    }
109	
110	    const { page = 1, limit = 20, ...filters } = matchedData(req, {
111	      locations: ['query']
112	    });
113	
114	    const pagination = {
115	      page: parseInt(page, 10),
116	      limit: Math.min(parseInt(limit, 10), 100) // Hard-cap
117	    };
118	
119	    const [items, total] = await Promise.all([
120	      impl.fetchPrompts(filters, pagination),
121	      impl.countPrompts(filters)
122	    ]);
123	
124	    const totalPages = Math.ceil(total / pagination.limit);
125	
126	    res.status(httpStatus.OK).json({
127	      data: items,
128	      meta: { total, totalPages, ...pagination, version }
129	    });
130	
131	    logger.debug('Prompt list fetched', { version, pagination, filters });
132	  } catch (err) {
133	    logger.error('List prompt failed', { err, version });
134	    next(err);
135	  }
136	}
137	
138	/**
139	 * POST /:version/prompts
140	 * Submit a user-generated prompt
141	 */
142	async function createPrompt(req, res, next) {
143	  const version = req.params.version || 'v1';
144	  const impl = selectVersionedImplementation(version);
145	
146	  try {
147	    const errors = validationResult(req);
148	    if (!errors.isEmpty()) {
149	      return res.status(httpStatus.BAD_REQUEST).json({ errors: errors.array() });
150	    }
151	
152	    const payload = matchedData(req, { locations: ['body'] });
153	    const newPrompt = await impl.savePrompt(payload);
154	
155	    metrics.userPromptCounter.inc();
156	    res.status(httpStatus.CREATED).json({ data: newPrompt, meta: { version } });
157	
158	    logger.info('New prompt created', { id: newPrompt.id, version });
159	  } catch (err) {
160	    // Duplicate titles cause 409, all else bubble
161	    if (err.code === 'ER_DUP_ENTRY' || err.code === 11000) {
162	      return next(createError(httpStatus.CONFLICT, 'Prompt already exists'));
163	    }
164	    logger.error('Creating prompt failed', { err, version });
165	    next(err);
166	  }
167	}
168	
169	/**
170	 * GET /:version/prompts.csv
171	 * Downloads prompts as CSV
172	 */
173	async function downloadPromptsCSV(req, res, next) {
174	  const version = req.params.version || 'v1';
175	  const impl = selectVersionedImplementation(version);
176	
177	  try {
178	    const csvStream = await impl.exportPromptsAsCSV();
179	    // Attach headers for download
180	    res.setHeader('Content-Type', 'text/csv');
181	    res.setHeader(
182	      'Content-Disposition',
183	      `attachment; filename="canvaschord_prompts_${version}.csv"`
184	    );
185	    csvStream.pipe(res);
186	    logger.info('Prompt CSV streamed', { version });
187	  } catch (err) {
188	    logger.error('CSV export failed', { err, version });
189	    next(err);
190	  }
191	}
192	
193	/* ───────────────────────────────────────────────────── GraphQL Hooks ──────── */
194	
195	/**
196	 * GraphQL resolvers delegate into the same controller as REST calls.
197	 * While GraphQL does not have `req/res`, we adapt argument lists
198	 * accordingly and surface the exact same metrics & logging.
199	 */
200	const gqlResolvers = {
201	  Query: {
202	    prompt: async (_, args, ctx) => {
203	      const impl = selectVersionedImplementation(args.version || 'v1');
204	      try {
205	        const endTimer = metrics.randomPromptDuration.startTimer();
206	        const prompt = await impl.generateRandomPrompt(args.filters || {});
207	        endTimer();
208	        logger.info('GraphQL prompt delivered', {
209	          userId: ctx.user?.id,
210	          version: args.version
211	        });
212	        return prompt;
213	      } catch (err) {
214	        logger.error('GraphQL prompt error', { err });
215	        throw err;
216	      }
217	    },
218	    prompts: async (_, args) => {
219	      const impl = selectVersionedImplementation(args.version || 'v1');
220	      return impl.fetchPrompts(args.filters || {}, args.pagination || {});
221	    }
222	  },
223	  Mutation: {
224	    createPrompt: async (_, { input, version = 'v1' }, ctx) => {
225	      const impl = selectVersionedImplementation(version);
226	      const prompt = await impl.savePrompt({ ...input, createdBy: ctx.user?.id });
227	      metrics.userPromptCounter.inc();
228	      return prompt;
229	    }
230	  }
231	};
232	
233	/* ─────────────────────────────────────────────────────────── Exports ──────── */
234	
235	module.exports = {
236	  /* REST */
237	  getRandomPrompt,
238	  listPrompts,
239	  createPrompt,
240	  downloadPromptsCSV,
241	
242	  /* GraphQL */
243	  gqlResolvers
244	};
